import type { MetadataRoute } from "next";

// The web app manifest: what phones and browsers use when someone installs
// Marquee ("Add to Home Screen"). Icons are generated by scripts/brand-assets.mjs.

export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Marquee",
    short_name: "Marquee",
    description: "What’s worth watching, tonight. Movies and TV, powered by TMDB.",
    start_url: "/",
    display: "standalone",
    background_color: "#0e0f11",
    theme_color: "#0e0f11",
    icons: [
      { src: "/brand/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/brand/icon-512.png", sizes: "512x512", type: "image/png" },
      // "maskable": Android may crop it into a circle or squircle, so the symbol sits well inside.
      { src: "/brand/icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
